-- 022_claim_coverage_master.sql
-- Refactors claim_coverage from per-claim transaction to master catalog
-- Seeds all reference data from ClaimMaster.txt (SQL Server -> PostgreSQL)
-- Run AFTER 021_backfill_screen_permissions.sql

-- Step 1: Remove old per-claim rows (ON DELETE CASCADE handles claim_coverage_asset)
DELETE FROM claim_coverage_asset;
DELETE FROM claim_coverage;

-- Step 2: Alter claim_coverage to master catalog schema
ALTER TABLE claim_coverage
    DROP CONSTRAINT IF EXISTS claim_coverage_claim_id_fkey;
DROP INDEX IF EXISTS idx_claimcoverage_claimid;
ALTER TABLE claim_coverage DROP COLUMN IF EXISTS claim_id;

ALTER TABLE claim_coverage
    ADD COLUMN IF NOT EXISTS created_by               bigint,
    ADD COLUMN IF NOT EXISTS created_on               timestamptz NOT NULL DEFAULT now(),
    ADD COLUMN IF NOT EXISTS updated_by               bigint,
    ADD COLUMN IF NOT EXISTS updated_on               timestamptz,
    ADD COLUMN IF NOT EXISTS coverage_limit           varchar(100),
    ADD COLUMN IF NOT EXISTS is_ho_physcial_damage    boolean,
    ADD COLUMN IF NOT EXISTS is_ho_personal_liability boolean;

-- Make client_id nullable (master data is shared across clients)
ALTER TABLE claim_coverage
    DROP CONSTRAINT IF EXISTS claim_coverage_client_id_fkey,
    ALTER COLUMN client_id DROP NOT NULL;

-- Step 3: Create claim_coverage_limit
CREATE TABLE IF NOT EXISTS claim_coverage_limit (
    id                                        bigserial    PRIMARY KEY,
    claim_coverage_id                         bigint       REFERENCES claim_coverage(id),
    asset_type                                varchar(100),
    basic_claim_code                          varchar(50),
    basic_limit                               varchar(100),
    basic_aggregate_limit                     varchar(100),
    basic_deductible                          varchar(100),
    standard_claim_code                       varchar(50),
    standard_limit                            varchar(100),
    standard_aggregate_limit                  varchar(100),
    standard_deductible                       varchar(100),
    preferred_claim_code                      varchar(50),
    preferred_limit                           varchar(100),
    preferred_aggregate_limit                 varchar(100),
    preferred_deductible                      varchar(100),
    from_date                                 timestamptz,
    to_date                                   timestamptz,
    created_by                                bigint       NOT NULL DEFAULT 1,
    created_on                                timestamptz  NOT NULL DEFAULT now(),
    updated_by                                bigint,
    updated_on                                timestamptz,
    basic_is_percentile                       boolean,
    basic_max_limit                           decimal(18,2),
    basic_percentile_value                    decimal(18,8),
    standard_percentile                       boolean,
    standard_max_limit                        decimal(18,2),
    standard_percentile_value                 decimal(18,8),
    preferred_is_percentile                   boolean,
    preferred_max_limit                       decimal(18,2),
    preferred_percentile_value                decimal(18,8),
    basic_percentile_of_claim_coverage_id     bigint       REFERENCES claim_coverage(id),
    standard_percentile_of_claim_coverage_id  bigint       REFERENCES claim_coverage(id),
    preferred_percentile_of_claim_coverage_id bigint       REFERENCES claim_coverage(id)
);
CREATE INDEX IF NOT EXISTS idx_ccl_claim_coverage_id ON claim_coverage_limit(claim_coverage_id);

-- Step 4: Create cause_of_loss_description
CREATE TABLE IF NOT EXISTS cause_of_loss_description (
    id                              bigserial    PRIMARY KEY,
    claim_coverage_id               bigint       NOT NULL REFERENCES claim_coverage(id),
    reducing_deductible_description varchar(1000),
    is_percentile                   boolean,
    max_limit                       decimal(18,2),
    percentile_value                decimal(18,8),
    reduced_deductible              decimal(18,2),
    created_by                      bigint       NOT NULL DEFAULT 1,
    created_on                      timestamptz  NOT NULL DEFAULT now(),
    updated_by                      bigint,
    updated_on                      timestamptz,
    percentile_of_claim_coverage_id bigint       REFERENCES claim_coverage(id)
);

-- Step 5: Create cause_of_loss_group
CREATE TABLE IF NOT EXISTS cause_of_loss_group (
    id                              bigserial    PRIMARY KEY,
    claim_coverage_id               bigint       NOT NULL REFERENCES claim_coverage(id),
    group_type                      varchar(50),
    is_percentile                   boolean,
    percentile_value                decimal(18,8),
    max_limit                       decimal(18,2),
    reduced_group_deductibles       decimal(18,2),
    created_by                      bigint       NOT NULL DEFAULT 1,
    created_on                      timestamptz  NOT NULL DEFAULT now(),
    updated_by                      bigint,
    updated_on                      timestamptz,
    percentile_of_claim_coverage_id bigint       REFERENCES claim_coverage(id)
);

-- Step 6: Create cause_of_loss_group_description
CREATE TABLE IF NOT EXISTS cause_of_loss_group_description (
    id                           bigserial   PRIMARY KEY,
    cause_of_loss_group_id       bigint      REFERENCES cause_of_loss_group(id),
    cause_of_loss_description_id bigint      REFERENCES cause_of_loss_description(id)
);

-- Step 7: Create claim_impacted_coverage (per-claim transaction table)
CREATE TABLE IF NOT EXISTS claim_impacted_coverage (
    id               bigserial   PRIMARY KEY,
    claim_id         bigint      NOT NULL REFERENCES claim(id) ON DELETE CASCADE,
    coverage_id      bigint      REFERENCES claim_coverage(id),
    cause_of_loss_id bigint      REFERENCES claim_coverage(id),
    asset_type       varchar(200),
    client_id        bigint      NOT NULL REFERENCES client(id)
);
CREATE INDEX IF NOT EXISTS idx_claim_impacted_coverage_claimid ON claim_impacted_coverage(claim_id);
-- ─── Step 8: Seed claim_coverage ────────────────────────────────────────────
SELECT setval('claim_coverage_id_seq', (SELECT MAX(id) FROM claim_coverage));

-- ─── Step 9: Seed claim_coverage_limit ──────────────────────────────────────
SELECT setval('claim_coverage_limit_id_seq', (SELECT MAX(id) FROM claim_coverage_limit));

-- ─── Step 10: Seed cause_of_loss_description ────────────────────────────────
SELECT setval('cause_of_loss_description_id_seq', (SELECT MAX(id) FROM cause_of_loss_description));

-- ─── Step 11: Seed cause_of_loss_group ──────────────────────────────────────
SELECT setval('cause_of_loss_group_id_seq', (SELECT MAX(id) FROM cause_of_loss_group));

-- ─── Step 12: Seed cause_of_loss_group_description ──────────────────────────
SELECT setval('cause_of_loss_group_description_id_seq', (SELECT MAX(id) FROM cause_of_loss_group_description));


